"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def SQUARE_ROOT(n):
    if (n < 0):
        return 'ERROR'
    if ((n == 0) or (n == 1)):
        return n
    low = 0
    high = n
    while (low <= high):
        mid = ((low + high) / 2)
        if ((mid * mid) <= n):
            low = (mid + 1)
        else:
            high = (mid - 1)
    return high
